"""Editorial additions adapted from the host-supplied wiki snapshots."""
from content import PAGES,add,p,ul,ol,note,pic,table,check,disclosure,link
import json
from pathlib import Path

def expand():
 def pg(s):return next(x for x in PAGES if x['slug']==s)
 def insert(s,h,b):pg(s)['sections'].append((h,b))
 def child(s,t,d,sections,wiki,related):
  add(s,t,'Field references',d,sections,wiki,related=related)
  pg(s)['nav_hidden']=True
 for page in PAGES:
  page['sections']=[(h,b.replace('Smithing Anvil',"Blacksmith’s Bench").replace('Smithing_Anvil','Blacksmith%27s_Bench')) for h,b in page['sections']]
 insert('getting-started','Follow every tutorial step',p('Want exact material counts and directions? '+link('tutorial','Use the full Doric → Vannaka → Zanik walkthrough')+'. It explains what to collect, what to craft and why each lesson matters.'))
 child('tutorial','The tutorial, step by step','Learn survival, cooking and runes before setting off for the clan village.',[
 ('Accept or skip First Steps',p('At the ruined Temple of Saradomin in Temple Woods, speak to the Wise Old Man. Accept First Steps for the guided route below. Decline if you want to join friends immediately; the Wise Old Man then waits on the first floor of a ruined building at the far end of Bramblemead Village.')+note('Doing the lessons gives you practice, useful starter rewards and a Runecrafting tome when First Steps is complete. Skipping saves time; it does not equip you for dangerous areas. Ask a clan member to meet you and use our camp route.')),
 ('Doric: Getting Started',ol(['Speak to Doric outside the temple. Use the interaction prompt to collect dirty water from a nearby pond. Dirty water needs boiling before it becomes a safe drink.','Collect <strong>10 Ash Logs and 8 Stone</strong>. Loose branches and stones are a good starting point.','Open Build Mode and place a Crafting Table using <strong>4 Ash Logs</strong>. Interact with the table.','Craft a Stone Club with the remaining <strong>6 Ash Logs + 8 Stone</strong>. Put it on your action bar and equip it.','Return to Doric with the club. He gives you Vegetable Soup and directs you to Vannaka.'])+pic('CraftingTable','Use a workstation’s recipe list to see what it can make and which materials you are missing.')),
 ('Vannaka: Ratcatcher',ol(['Find Vannaka north-east of Doric, south of the windmill. Accept the rat hunt.','Defeat four Giant Rats and collect their Raw Rat Meat. Leave enough stamina to dodge; fight one at a time where possible.','Build a Campfire with <strong>4 Ash Logs + 4 Stone</strong>. Bring additional logs for fuel.','Place meat in the cooking slot and fuel in its slot. Cook at least <strong>2 Rat Roasts</strong> and take the finished food out.','Return to Vannaka. Your rewards include a Stone Logging Axe and a Stone Dagger.'])+pic('Campfire_basicCooking','A campfire turns raw ingredients into useful food. Remember both the fuel and the finished output.')),
 ('Zanik: Rune Mysteries',ol(['Follow the road east to Zanik. Gather <strong>50 Ash Logs</strong> for her objective and speak to her again. She supplies a Stone Pickaxe.','Mine Stone and Rune Essence. Build a Rune Altar with <strong>12 Stone + 4 Rune Essence</strong>. Keep extra essence for making runes.','Use the altar to craft Air and Astral Runes as directed by the active quest. One essence produces a batch of runes; the altar’s building cost is separate.','Follow Zanik’s current spell instructions. Check your spellbook for the rune cost before casting.','Return to Zanik for Air Runes, Astral Runes and a Woodcutting tome. Then return to the Wise Old Man in Bramblemead Village to finish First Steps.'])+note('Read the highlighted Journal objective after each conversation. Collecting an item, crafting it and talking to the character are separate steps; having materials in your bag alone may not complete the objective.')),
 ('From the tutorial to home',p('Bramblemead Village is a quest destination. DragonInfinity’s basecamp is a separate player-built location. '+link('basecamp','Follow the host’s annotated camp route')+' and ask which bed you may claim.')+check('tutorial',['Doric: Stone Club crafted and returned.','Vannaka: rats defeated, food cooked and reward collected.','Zanik: altar built, runes made and reward collected.','Wise Old Man: First Steps completed.','Camp: available bed claimed and spare supplies stored.']))
 ],['First_Steps','Getting_Started','Ratcatcher','Rune_Mysteries'],['basecamp','crafting','magic'])
 insert('quests','Walkthrough library',p('These guides reveal quest objectives and solutions. Open only the chapter you are ready to play.')+ul([link(s,t) for s,t in [('tutorial','First Steps: the complete tutorial'),('dragon-slayer','Dragon Slayer: prepare for Velgar'),('withering-heights','Withering Heights: Fellhollow and Imaru'),('black-knights-fortress','Black Knight’s Fortress: all 13 shards'),('icthlarins-helper','Icthlarin’s Little Helper: three clans and Fuzan'),('regicide','Regicide: the road to Kuldra')]]))
 child('dragon-slayer','Dragon Slayer','Follow Cathan’s trail, make the Dragonkin Horn and face Velgar.',[
 ('Before you set out',p('Start with the Wise Old Man in Bramblemead Village after First Steps. Prepare a sheltered, claimed bedroll and a reliable source of food. Deer provide antlers; a ranged weapon makes hunting easier. Work through the Journal’s preparations before pushing into dangerous regions.')+note('This walkthrough contains story and boss spoilers. Upgrade your equipment as you travel; a quest marker is not a promise that your current gear is strong enough.','Quest preparation')),
 ('Follow the blue flames',ol(['Explore the Keep of the Blue Flames and find Cathan’s journal in the chest at the top. Be ready to move out of Velgar’s poison after the encounter.','In Whispering Swamp, enter the blue-flame vault Vertentis Kara. Work through it and speak to Spitfoot at the end. Return to the Wise Old Man.','Continue to Velgar’s Rise in Ghornfell’s Fractured Plains. Cathan’s ghost explains the Dragonkin Horn.'])),
 ('Make the Dragonkin Horn',table(['Material','Where and how'],[['1 Dragon Tooth','Use an Iron Pickaxe on the dragon skull in western Stormtouched Highlands, beyond the Garou skeleton settlement.'],['1 Bloodwood Sap','Use an Iron Logging Axe on the Bloodwood Tree at the southern castle in Bloodblight Swamp. Prepare for poison.'],['5 Bronze Bars','Smelt copper and tin in a Furnace. Use the recipe finder to plan your materials.']])+p('Craft the horn with the unlocked recipe. Bring food, repaired equipment, healing and antipoison supplies before taking it to the Dragonkin Altar at the top of Velgar’s Rise.')),
 ('Survive Velgar',ul(['Watch the ground: poison spray and lingering pools restrict where you can stand. Move to clear ground before attacking.','At close range, expect bites, head swings and leg attacks. Dodge the tell, then make a short attack; do not spend all your stamina.','At roughly 75%, 50% and 25% health, Velgar takes flight and sends poison across the arena. Stay mobile and watch the next corner for the landing.','Keep a clear escape route. If a teammate needs help, deal with the ground hazards before attempting a rescue.'])+p('Leave inventory space for the head. After victory, return to the Wise Old Man outside the tower to finish the quest.'))
 ],['Dragon_Slayer','Velgar','Dragonkin_Horn'],['combat','bosses','withering-heights'])
 child('withering-heights','Withering Heights','Enter Fellhollow, recover three curse fragments and challenge Imaru.',[
 ('Enter Fellhollow',ol(['After Dragon Slayer, speak to the Wise Old Man near Ashien’s Watch. Follow his dialogue to enter the Forgotten Temple.','Speak to Death and Postie Pete. Crossing wither water puts you into Soulrift, allowing passage through the spectral doorway into the Bleakfields.','Head for the purification fountain marked by a blue beacon and compass indicator. Break the spectral tangles around it, then purify yourself.','Speak to Cathan near the cliff and read the three tablets. Your next goal is three curse fragments.'])+note('Soulrift is a gameplay state, not simply a visual effect. Lingering in it brings increasingly dangerous hostile souls. Learn the way to purification before exploring widely.')),
 ('Grief: the four shrines of Emberwood',table(['Shrine','What to do'],[['Guthix','At the western druid circle, defeat the Green Dragon and use the altar.'],['Saradomin','North-east, find the lone rock in the small lake. Repair the submerged symbol and interact with it.'],['Armadyl','At the river island east of Guthix, solve the crime dialogue. The supplied walkthrough’s option order is 3 → 2 → 3 → 3; follow the dialogue meaning if options change.'],['Zamorak','Enter the temple through its roof, use the altar and pull the lever to open the exit.']])+p('Activating all four removes the barrier to the Fragment of Grief.')),
 ('Rage and Despair',ul(['<strong>Rage:</strong> enter Vekchenven Kara beneath the waterfall at Lake of Lost Souls. Complete the vault and defeat its Zogre to obtain the fragment.','<strong>Despair:</strong> ascend Silverthorn Keep through the undead. Defeat the Green Dragon near the curse seal, then interact with the seal.'])),
 ('Hope’s Fall and Imaru',p('Bring all three fragments to the seal at Hope’s Fall. The supplied walkthrough recommends Power Level 5, with food and potions prepared. Repair before entering.')+ul(['Imaru changes the fight through Soulrift. Watch the arena state and do not let wandering souls become free healing for the boss.','Four purification pools are available around the arena. Use them deliberately while avoiding wither rot.','Prioritise positioning and survival when the state changes. Re-establish control before committing to damage.'])+p('Keep inventory space for Imaru’s head. After the fight, return to Death to complete the quest.'))
 ],['Withering_Heights','Imaru','Soulrift'],['safety','black-knights-fortress','combat'])
 shards=[('Cathedral · south-west','Cut the vines with a Mithril Logging Axe after dealing with the mages.'),('Garrison · east','Defeat Sergeant Blister in the underground area with hellhounds and skeletons.'),('Garrison · west','Reach the adjacent tower using Windstep and defeat the elite knight.'),('Grand Hall · east','Give Spittletoe 5 Maple Sap.'),('Library · north-west','Read the books in order: The Empty Throne → The Eye of Oculus → Taking the Crown → Zamorak’s Rebellion. Defeat the two shardbound Lesser Demons.'),('Library · south-west','Speak to Valerius. From the upper-level western stairs, pass the Blue Dragon and turn right beneath the cliff. Dig near the gargoyle for the glass owl and return it.'),('Menagerie · south','Operate three levers: dig in the small broken-roof house near the windmill, cut the cave’s vine wall, and reach the high stone ruins by the air anima vent. Expect a Lesser Blue Dragon.'),('Menagerie · south-east','Follow the lower-cliff beams and jumps. Bring Air Runes for Windstep and treat missed jumps as dangerous.'),('Pastures · north','At the highest goblin fort, mine the granite deposit hiding the shard.'),('Pastures · east','Clear the goblins and collect the shard.'),('Crypt · underground','Defeat the Zogre, read the note on the goblin corpse and dig the graves. The correct grave can vary by world.'),('Demon Gate · underground','Use the lever-operated lift, activate the nodestone below and defeat the two demons.'),('Lake · underground','Speak to Offalfoot and fish for the Unusual Trout. Bring a rod and leave an inventory slot free; Fishing level 1 is enough.')]
 child('black-knights-fortress','Black Knight’s Fortress','A practical checklist for Dowdun’s 13 Dreaming Stone shards.',[
 ('Open the way',ol(['After Withering Heights, speak to Death in the Forgotten Temple. Meet Cathan at the ominous gate south of Silverthorn Keep, east of Fellhollow.','Travel through the Approach into the Courtyard and speak to the Wise Old Man at the base.','Go to the Nexus and speak to Doric. Inspect the Dreaming Stone: you need 13 shards. Activate nodestones as you explore to make return trips easier.'])),
 ('Pack before leaving',ul(['A Steel or Undead Spade, a suitable pickaxe (Steel or better is a useful expedition choice) and a Mithril Logging Axe.','A Fishing Rod, five Maple Sap and Air Runes for Windstep.','Food, healing, repaired equipment and spare inventory space.'])+note('Old walkthroughs sometimes rely on Feather Fall equipment to survive drops. Do not assume those older effects still apply. Use a safe route and your current spell descriptions.')),
 ('The 13-shard checklist',check('dreaming-shards',['<strong>'+a+':</strong> '+b for a,b in shards])),
 ('Restore the stone and face the Titan',ol(['Return all 13 shards to the Dreaming Stone and complete Doric’s dialogue. Choose the destruction option when asked to remove the barrier. Read the actual dialogue before selecting.','Enter the Bastion. Use Windstep for the broken stair gaps and prepare for the Titan encounter.','After defeating the Titan, return to the stone. The route into the Umbral Sands opens.'])+p('If another barrier blocks a route, check nearby nodestones and unresolved objectives. The Bastion barrier is tied to completing the shard objective.'))
 ],["Black_Knight%27s_Fortress",'Dreaming_Stone','Titan'],['icthlarins-helper','magic','safety'])
 child('icthlarins-helper','Icthlarin’s Little Helper','Earn the trust of three Garou clans, recover the lenses and open the Burning Spire.',[
 ('Arrive in the Umbral Sands',p('After the Titan, follow Avisk’s objective through the Bastion doorway. At Alcarrid Oasis, meet Shangruuh, Ancamairon and Icthlarin. Three clans hold the lenses needed to repair the mirrors.')+note('Prepare drinks and food that help against Scorch, and consider travelling after resting for the night. Bring a spade, a Mithril Pickaxe or better, and an Adamant Logging Axe for the relevant gathering tasks.')),
 ('Alcarrid: earn your first lens',table(['Character / task','What to bring or do'],[['Domri · Rogue Trader','Gather 3 Moonstones from the marked gypsum nodes to the west with a Mithril Pickaxe.'],['Valas · Mirror, Crack’d','Provide 3 Adamant Bars. If smelting them, plan for 9 Adamantite Ore and 9 Coal.'],['Lagra · Rag and Bone','Bring 3 raw farm meats from goats or vultures, 3 Kalphite Shell Fragments and 3 Cactus Steaks. Bunny cactus needs an Adamant Logging Axe.']])+p('Return to the clan elder after finishing the tasks to receive the lens and progress the quest.')),
 ('Manafem: recover stories and find Efina',ul(['<strong>Laguna:</strong> enter the vault south of the camp at the marked Kalphite nest. Use the Scarab Staff to manage the scarabs. Find three statues: the first right after the staff, another east of the lever, and one on a platform reached with Windstep. Bring Air Runes. The optional Kalphite Queen route is not required for this step.','<strong>Hedric:</strong> investigate the three clues east of camp, including the bodies and scorch marks. Continue east and defeat the Red Dragon for the Radiant Heart. Return to Hedric.','<strong>Manathep:</strong> find Efina by following Dearg Due west of the pyramid in the sandstorm. Give her one Clean Water and return.'])+p('Report to elder Dushlanach once the clan tasks are complete.')),
 ('Uzzer: records, monuments and councillors',ul(['<strong>Lehran:</strong> dig up four scrolls at the southern ruins: Schism, Sun Demon, Old Kingdom and Moon Goddess. Some are behind gates; defend against Kot-Haar.','<strong>Laguna:</strong> investigate the statues at four rock spires around the pyramid. Bring a torch and a pickaxe for blocked sandstone caves. The final statue is by the Nightmare Crucible of Humiliation. Return to Laguna.','<strong>Shangruuh:</strong> persuade the three councillors. Alabrais needs the evidence about Fuzan’s control and destruction. Brialka responds to the history of choice and strength through Garou unity. Chirot’s argument concerns the cost of action and what Fuzan takes.'])+disclosure('Councillor dialogue hints',p('Follow the meaning of the choices, since wording can change. For Alabrais: Fuzan seeks control like the Kot-Haar; the evidence points to destruction; control remains constant. For Brialka: each generation chooses; alliances made the Garou stronger; unity helped them survive. For Chirot: action costs money; consider wealth before and after Fuzan’s share; Fuzan steals what Chirot hopes to take.'))+p('Return to elder Gaimbin for the clan’s lens.')),
 ('The mirrors, the trials and Fuzan',ol(['Return to Icthlarin with all three lenses. Repair the three mirrors to open the Burning Spire gateway.','Prepare a complete combat loadout before entering the Fight Caves. The Trials of Fuzan contain ten waves; use the breaks to reassess supplies.','Continue to Fuzan’s lair, defeat him and take the head back to complete the quest.'])+note('This is the quest route, not a complete wave-by-wave combat reference. Use the linked wiki pages for encounter detail, and agree on a group plan before entering.'))
 ],["Icthlarin%27s_Little_Helper",'Trials_of_Fuzan','Fuzan'],['bosses','regicide','resources'])
 child('regicide','Regicide','Prepare for the Scorned Wild and the conclusion of the Kuldra Saga.',[
 ('Reach Rasthin’s Rest',ol(['Complete Icthlarin’s Little Helper. Travel to the Dragon Gate north-west of Velgar’s Rise in the Fractured Plains.','Enter the Scorned Wild to the north and find Zilyana at Rasthin’s Rest.','Use the permitted hub area to prepare. Coordinate equipment, supplies and roles before starting the raid at Dragontail Vines.'])),
 ('Prepare as a group',check('regicide',['Everyone has completed the required quest progression.','Weapons, armour and tools are repaired.','Food, healing and the runes or ammunition each player needs are packed.','The group has discussed movement, revival and retreat.','Everyone understands that building is restricted inside the raid.'])+note('The supplied Regicide page describes the route and rewards but does not document every raid mechanic. Read the Scorned Wild and Kuldra wiki guides before committing to the encounter; do not treat this checklist as a full raid strategy.')),
 ('Finish the saga',p('Complete the raid and defeat Kuldra, then return to Zilyana. Listed rewards include the Dragon Kiteshield, Dragonslayer Cape, Queenslayer Pack and Lougrim’s Staff. For the optional follow-up, take the staff to Ancamairon at the shrine.')+p('Completing the saga gives the shared adventure a milestone. Building, skilling, gathering and helping the next new arrival remain worthwhile goals afterwards.'))
 ],['Regicide','Scorned_Wild','Kuldra'],['bosses','combat','community'])
 # Skill and system references
 child('gathering-tiers','Tools & gathering tiers','Match your tool to the material before making a long expedition.',[
 ('Mining: which pickaxe?',table(['Pickaxe','New materials at this tier'],[['Stone','Stone, Rune Essence, Clay'],['Bone','Copper, Tin, Sandstone'],['Bronze','Iron, Silver, Granite, Blurite'],['Iron','Gold, Coal, Dragon Tooth'],['Steel','Mithril'],['Mithril','Adamantite, Limestone, Gypsum'],['Adamant','Runite'],['Rune','Highest-tier mining; check the current node prompt.']],True)+p('Higher tiers retain access to earlier materials. If a node refuses your tool, read its requirement instead of repeatedly swinging. The table follows the supplied Mining snapshot; newly added resources may have separate requirements.')+pic('OreNodeMining_Non_Mineable','A node can be visible long before you have the tool needed to mine it.')),
 ('Woodcutting: which axe?',table(['Logging axe','Additional trees at this tier'],[['Stone','Ash'],['Bronze','Oak'],['Iron','Willow, Blightwood, Bloodwood'],['Steel','Dead trees, Thorny Irit'],['Mithril','Maple'],['Adamant','Yew'],['Rune','Magic']],True)+p('Use normal swings on a standing tree and overhead chops on fallen timber. Position so falling trees and enemies do not trap you. Preserve stumps if you want trees to regrow; the saved pages disagree on exact real-world respawn timing, so this guide does not promise a timer.')),
 ('Skill spells that change gathering',table(['Unlock','Practical use'],[['Mining 11 · Rocksplosion','Break nearby rock within the spell’s area. Useful for clustered deposits.'],['Mining 24 · Stone Spirits','Help locate a nearby clay or ore deposit; a direction hint still needs a safe route.'],['Mining 80 · Divine Rock','Uses five ore to transform a node. Read the current spell costs before casting.'],['Woodcutting 11 · Axtral Projection','A magical aid for cutting trees. Bring the required runes.'],['Woodcutting 27 · Splinter','Helps process fallen logs.'],['Woodcutting 52 · Trunk Totem','A later gathering aid; consult the current spell description.']])+note('Level unlocks give you options, not free casts. Carry the required runes and consider whether a spell saves enough time to justify its materials.'))
 ],['Mining','Woodcutting'],['resources','magic','recipe-finder'])
 child('fishing','Fishing without the frustration','Choose a fishing spot, read the line and bring your catch home.',[
 ('Nets and rods do different jobs',p('Use a fishing net at net-fishing spots. The trawl action uses stamina; a depleted spot stops producing fish. A rod belongs at rod-fishing spots. Casting at ordinary water is not the same as fishing an active spot.')),
 ('Your first rod catch',ol(['Equip a suitable rod at a rod-fishing spot. Charge the cast to set distance. Bait is optional and helps reduce junk.','Wait for a bite. Follow the on-screen prompts and pull against the fish’s direction (A/D on the default keyboard layout).','Watch the tension bar. If it turns dangerous, ease off and respond to the fish changing direction.','When the fish tires, release the directional pull and reel using the cast action. Stop reeling when it resumes swimming, then repeat.','Take the catch and leave room in your bag for more. Cook appropriate fish before eating.'])),
 ('Match the rod to the region',table(['Rod','Region'],[['Ash','Brynmoor'],['Oak','Ghornfell'],['Willow','Fellhollow'],['Maple','Dowdun'],['Yew','Umbral Sands']])+p('The supplied guide recommends matching the rod to the region to reduce junk. Higher-tier rods also affect durability and stamina handling. Check your rod’s tooltip and the spot before travelling.')),
 ('Make fishing useful to the camp',p('Check which fish the cook needs, bring spare inventory capacity and store raw catches in the agreed food chest. Use '+link('recipe-finder','the recipe finder')+' to look for recipes that use a particular fish.'))
 ],['Fishing'],['resources','crafting','safety'])
 child('inventory','Inventory, weight & equipment','Understand what you are carrying and what is actually helping you.',[
 ('A slot is not the same as weight',p('Your bag can become heavy before it runs out of spaces. The standard starting weight limit in the supplied snapshot is 400. Equipment, perks and server settings can change your situation; read the current displayed limit.')+p('Over the limit, you become encumbered: running and jumping are unavailable, movement slows and automatic pickup stops. Leave ore or timber in appropriate storage before setting off again.')+pic('AbilityBarAndInventoryAndPowerLevel','Check carried weight, quick-access items and equipped gear separately.')),
 ('Use the right inventory section',ul(['Runes, ammunition and quest items have their own inventory sections. Check those tabs before deciding an item is missing.','Putting a weapon in your bag does not equip it. Assign it to the action bar and select it.','Compare equipment power, durability and useful effects. A stronger item left broken or unequipped will not help you.','Keep at least one spare slot for quest rewards and important boss drops.'])),
 ('Pack for the trip you are making',check('packing',['Food and useful drinks, with enough duration for the return.','The tool tier required by the target resource.','Runes or ammunition for the actions I intend to use.','Repaired combat gear and a clear way home.','Enough spare weight and slots for the planned haul.'])+note('Death-drop behaviour can be changed by the host. Ask what DragonInfinity currently uses before carrying valuables; do not rely on another server’s rules.'))
 ],['Inventory','Player_Character'],['safety','resources','combat'])
 child('agility','Agility & getting around','Travel efficiently without turning a shortcut into a rescue mission.',[
 ('Train while exploring',p('Travelling on foot contributes to Agility, while mounted travel does not provide the same passive training. Agility helps stamina use and unlocks movement options. Courses, beginning with Chasm Dash, offer a focused way to practise.')),
 ('Use movement abilities deliberately',ul(['<strong>Windstep:</strong> an Agility movement spell. Check its current rune cost before attempting a gap; older guides may place it under Runecrafting.','<strong>Recall:</strong> understand the tether and return conditions before relying on it. Test in safe terrain first.','<strong>Phase Dash:</strong> another mobility tool. Learn its range and recovery before using it near a drop.','<strong>Kebbit burrows:</strong> shortcuts may hurt an underlevelled adventurer. Read the requirement and consider the normal path.'])+note('A roll or movement perk is not a guarantee against fatal falls. Do not jump from a cliff on the strength of an old equipment guide.')),
 ('Navigate with a return plan',p('Mark your destination, note the last safe landmark and identify a route back before you descend. Sprinting until empty leaves no stamina for an unexpected enemy. Keep enough reserve to evade.'))
 ],['Agility'],['basecamp','keybinds','safety'])
 child('lore','Ashenfall: a short field history','The people, powers and old conflicts behind the place you are exploring.',[
 ('A fresh start on an old continent',p('Your adventurer comes to Ashenfall seeking a fresh start. The continent is saturated with anima, the magical energy behind its unusual life and powerful abilities. Ruins are more than scenery: they connect your survival journey to the history of RuneScape’s world.')+p('Dragonwilds uses the RuneScape setting and familiar characters, while telling a survival adventure on Ashenfall. Shared names do not mean every Old School RuneScape storyline happened in exactly the same way.')),
 ('The powers you will hear about',table(['Name','A useful first association'],[['Guthix','Balance; his protection and the continent’s isolation matter to its history.'],['Saradomin','Order and faith; temples and followers carry his influence.'],['Zamorak','Chaos and self-determination.'],['Armadyl','Justice.'],['Bandos','War and the conflicts of his followers.'],['Lougrim','The moon and the hunt, central to Garou tradition.'],['Icthlarin','The passage of the dead; a guide whose role becomes important later.']])+p('These are starting associations, not a complete account of each god or follower. The linked Gods article explores their histories in more detail.')),
 ('The older story — optional spoilers',disclosure('Why Ashenfall’s past still matters',p('The supplied histories describe Guthix shielding persecuted people changed by anima, the Amalgamated. Dragonkin later arrived and left experiments and vaults across the continent. Conflicts involving humans, goblins and the Garou reshaped its settlements.')+p('Those old struggles remain visible in the places you explore. Velgar’s blood and poison connect to the blighted landscape; Dragonkin artefacts and the threat of Kuldra draw your expedition into a much larger conflict.'))),
 ('Your place in the story',p('The Kuldra Saga takes you from basic survival to helping communities and confronting dragons. Each new region asks you to improve tools, supplies and knowledge. The practical loop—gather, craft, explore, return—supports the narrative rather than sitting apart from it.'))
 ],['History','Gods','Saga','Player_Character'],['overview','quests','regicide'])
 # Workstations and recipes
 data=json.loads((Path(__file__).resolve().parent.parent/'assets/recipes.json').read_text())
 station_rows=[]
 for s in data['stations']:
  station_rows.append([s['name'],', '.join(str(i['quantity'])+' '+i['name'] for i in s['ingredients']) or 'See the linked workstation article.'])
 child('workstations','Workstations & production chains','Build the right station, then understand what goes in and what comes out.',[
 ('Start with the job',p('A Crafting Table handles early essentials. Later equipment is split across specialised benches. The Blacksmith’s Bench replaced the older Smithing Anvil; Armour Bench, Fletching Bench and Mystic Forge serve different equipment types.')+p('Use '+link('recipe-finder','the recipe finder')+' to identify the correct station for an item before spending materials on construction.')),
 ('Station construction costs',table(['Station','Building materials'],station_rows,True)+note('These are construction costs extracted from your saved wiki pages, not upgrade costs. Unlock conditions and placement rules still apply.')),
 ('Placement and unlocking',table(['Station','Useful requirement'],[['Furnace','Acquire copper or tin to unlock. Uses charcoal as fuel; no roof required. It smelts metal, rather than firing clay.'],['Kiln','Acquire clay to unlock. Converts wood into charcoal and swamp tar into adhesive. Can operate indoors.'],['Spinning Wheel','Acquire flax; roof required. Produces thread from fibre or suitable fur.'],['Tannery','Acquire bone to unlock. No roof required in the newer snapshot. Upgrades allow recipes with more inputs.'],['Loom','Acquire Bronze Bars; roof required. Turns thread into cloth.'],['Armour / Blacksmith’s / Fletching / Mystic benches','Acquire Bronze Bars to unlock this workstation tier. The Fletching Bench requires shelter.'],['Jeweler’s Bench','Acquire a Silver Bar to unlock.'],['Cooking Range','Cooking level 16 and the relevant campfire/ingredient discovery. Requires a roof.'],['Rune Altar','No special placement requirement listed. Keep extra essence for runes after paying its build cost.']])+p('For benches without a roof rule listed here, follow the current placement prompt. Space, terrain and updates can affect whether a location is valid.')),
 ('Three useful production chains',ol(['<strong>Metal gear:</strong> logs → Kiln → Charcoal; ore + Charcoal → Furnace → bars; bars and other components → the equipment’s specialised bench.','<strong>Clothing:</strong> flax or fur → Spinning Wheel → thread; thread → Loom → cloth; cloth and other components → the appropriate equipment bench.','<strong>Runes:</strong> Rune Essence → Rune Altar → rune batches. Manual attunement gives more Runecrafting experience than leaving production automatic. Mining essence itself no longer grants Runecrafting XP in the newer patch note.'])),
 ('Why is nothing happening?',ul(['Check input slots, fuel, output space and any required upgrade.','Make sure the station has the shelter it needs.','Look for the station’s interaction prompt rather than its build menu.','Take finished items from output slots; they may not transfer to your bag automatically.']))
 ],["Blacksmith%27s_Bench",'Armour_Bench','Mystic_Forge','Furnace','Kiln','Tannery','Spinning_Wheel','Loom','Rune_Altar','Cooking_Range'],['crafting','recipe-finder','building'])
 child('recipe-finder','Recipe finder & material planner','Search 468 recipes from the supplied wiki snapshots and calculate the inputs for a crafting batch.',[
 ('Find a recipe', '<div id="recipe-app"><div class="recipe-filters"><label>Item or ingredient<input id="recipe-search" type="search" placeholder="Try bronze, wool or salmon…"></label><label>Workstation<select id="recipe-station"><option value="">All 12 stations</option></select></label></div><p id="recipe-count" class="small" role="status"></p><div class="recipe-layout"><div><div id="recipe-list" aria-label="Matching recipes"></div><button id="recipe-more" class="button secondary" hidden>Show more recipes</button></div><div id="recipe-detail" aria-live="polite"></div></div></div><noscript><p>The calculator needs JavaScript. See the workstation construction table and linked wiki recipes for a readable alternative.</p></noscript>'),
 ('How to read the calculator',ul(['A <strong>batch</strong> is one recipe execution. Some recipes produce more than one item per batch.','Inputs are multiplied by your batch count. The planner does not recursively add ingredients for components you might craft separately.','Alternative recipes are separate entries. Choose the version matching the materials you have.','Costs describe the saved wiki recipe, before any personal bonuses or custom server modifiers. Fuel and workstation construction are separate.'])+note('This is an offline snapshot, not a live connection to the wiki. Check the in-game recipe when materials differ and use the source link on the selected recipe.')),
 ('Plan the full workshop',p(link('workstations','View workstation construction costs and production chains')+'. The planner covers the 12 supplied station recipe tables; it is not an exhaustive database of every item in Dragonwilds.'))
 ],['Furnace','Rune_Altar','Mystic_Forge','Armour_Bench'],['workstations','resources','crafting'])
 insert('skills','Choose a practical skill reference',ul([link('gathering-tiers','Mining and Woodcutting: tools, tiers and spells'),link('fishing','Fishing: nets, rods and landing a catch'),link('agility','Agility: movement, shortcuts and safer travel'),link('inventory','Inventory: equipment, weight and trip preparation')]))
 insert('resources','Check the tool before the trip',p(link('gathering-tiers','Use the full mining and logging tier tables')+' to avoid arriving with an axe or pickaxe that cannot harvest your target. For food supplies, '+link('fishing','learn the rod-fishing sequence')+'.'))
 insert('crafting','Recipes and workshop planning',p(link('recipe-finder','Search 468 recipes and calculate batch materials')+'. You can filter by workstation or search an ingredient to find uses for spare supplies.')+p(link('workstations','Compare workstation build costs, unlocks and placement rules')+'.'))
 insert('overview','Explore the lore',p(link('lore','Read our short history of Ashenfall')+' for the gods, Garou, Dragonkin and the older conflicts behind the landscape. Major story details are tucked inside an optional spoiler panel.'))
 insert('building','Build for a shared settlement',ul(['Use the host’s designated building area. Keep walking routes and workstations accessible.','Ask about a Build Protection Totem and Lightning Rod before investing heavily in exposed structures. Read each item’s protection limits in game.','Use personal chests for personal supplies and agree on communal storage labels. A Storage Ledger can support organised settlement storage.','Repair damaged structures through Build Mode (default B), then the repair action (default T). Check walls and crafting areas after attacks.'])+p('For exact building categories and object requirements, consult the Buildings wiki reference below.'))
 pg('building')['wiki'].append('Buildings')
 insert('sources','Wiki adaptations and recipe data',p('The expanded quest, skill, lore and workstation references paraphrase the wiki HTML snapshots supplied by the host. Recipe names, quantities and station construction costs are extracted from those snapshots. Their underlying wiki content is credited to the RuneScape: Dragonwilds Wiki contributors under <a href="https://creativecommons.org/licenses/by-nc-sa/3.0/" target="_blank" rel="noopener">CC BY-NC-SA 3.0</a>. These adaptations and the recipe dataset are shared under that same licence. Each guide links its topic sources, and each recipe links its source table.')+p('The archive contained saved HTML but not the companion article-image folders. Screenshots shown here are the host-supplied media from the original package. No missing wiki images are referenced.'))
 # Keep the enlarged library discoverable without an unmanageable sidebar.
 add('library','Browse all guides','The essentials','Every walkthrough, skill reference and practical tool in one place.',[('Start somewhere useful', '<div class="directory">'+''.join('<a href="'+x['slug']+'.html"><span class="eyebrow">'+x['group']+'</span><strong>'+x['title']+'</strong><p>'+x['desc']+'</p></a>' for x in PAGES if x['slug']!='sources')+'</div>')],[],related=['getting-started','recipe-finder'])
